import { createServer } from 'node:http';
import { z } from 'zod';
import { resolve } from 'node:path';
import { spawn } from 'node:child_process';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { registerAppResource, registerAppTool, RESOURCE_MIME_TYPE } from '@modelcontextprotocol/ext-apps/server';

const espeakRoot=resolve('./.espeak-root/usr');
process.env.PATH=resolve('./.espeak-bin')+':'+espeakRoot+'/bin:'+process.env.PATH;
process.env.LD_LIBRARY_PATH=espeakRoot+'/lib/x86_64-linux-gnu:'+espeakRoot+'/lib:'+ (process.env.LD_LIBRARY_PATH||'');
delete process.env.ESPEAK_DATA_PATH;
const URI = 'ui://audio-test/piper-p225-kiss-v6.html';
let status = 'idle';
let audioData = null;
let errorMessage = '';
let job = null;
function htmlEscape(value) { return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'); }
async function generateHi() {
  const started = performance.now();
  status = 'loading'; errorMessage = '';
  try {
    const { PiperNativeTTS } = await import('pipertts');
    const tts = await PiperNativeTTS.load({ model: 'hub:warmf-english-en-medium', modelsDir: './models' });
    const loaded = performance.now();
    console.log('Piper model load seconds:', ((loaded-started)/1000).toFixed(2));
    status = 'generating';
    const { audio } = await tts.synthesize('You know, I was going to agree with you. Then I checked the mathematics.', { speakerId: 0 });
    audioData = 'data:audio/wav;base64,' + Buffer.from(audio).toString('base64');
    status = 'ready';
    console.log('Piper speech generation seconds:', ((performance.now()-loaded)/1000).toFixed(2));
    console.log('Piper total seconds:', ((performance.now()-started)/1000).toFixed(2));
    console.log('Piper WARMF greeting ready');
  } catch (error) {
    errorMessage = error?.message || String(error);
    status = 'error';
    console.error('Piper greeting failed:', error);
  } finally { job = null; }
}
function startGeneration() {
  if (status === 'ready' || job) return;
  job = generateHi();
}

const URI7='ui://audio-test/piper-dynamic-v7.html';
const BASE='https://np-douce-audio-test-mcp.onrender.com';
// All three DarkNightPrincess clips below are Freesound CC0 recordings.
// Keep the original Lemonjolly kiss and classic giggle for backward compatibility.
const effects={
 kiss:'https://cdn.freesound.org/previews/275/275345_3173139-hq.mp3',
 giggle_old:'https://cdn.freesound.org/previews/275/275343_3173139-hq.mp3',
 giggle:'data:audio/mpeg;base64,',
 oh:'data:audio/mpeg;base64,',
 sigh:'data:audio/mpeg;base64,'
};
const tasks=new Map();
let latestTask='';
// Keep complete phrases together so Piper can interpret commas and sentence intonation.
// Extra silence is only added BETWEEN synthesized chunks, never at every comma.
function smartSpeechChunks(input){
 const words=String(input).trim().split(/\s+/).filter(Boolean);
 const result=[];let current=[];
 function flush(){if(current.length){result.push(current.join(' '));current=[];}}
 for(let i=0;i<words.length;i++){
  const word=words[i];current.push(word);
  const end=/[.!?]["')\]]*$/.test(word)&&!/\b(?:Mr|Mrs|Ms|Dr|Prof|St|vs|etc)\.$/i.test(word)&&!/\d\.\d/.test(word);
  const soft=/[,;:]["')\]]*$/.test(word);
  // Prefer complete sentences; only split at commas if the sentence gets long.
  if(end||(current.length>=32&&soft)||current.length>=45)flush();
 }
 flush();return result;
}
function boundaryPause(text){
 const end=String(text).trim();
 if(/\.{3,}["')\]]*$/.test(end)||/…["')\]]*$/.test(end))return 450;
 if(/\?["')\]]*$/.test(end))return 300;
 if(/!["')\]]*$/.test(end))return 250;
 if(/\.[ "')\]]*$/.test(end))return 250;
 if(/[;:]["')\]]*$/.test(end))return 200;
 if(/,["')\]]*$/.test(end))return 100;
 return 90;
}
function parseScript(script){
 const pieces=String(script).split(/(\[(?:kiss|giggle-old|giggle|oh|sigh|pause:\s*\d{1,4}ms)\])/gi);
 const segments=[];
 for(const part of pieces){
  const p=part.trim();if(!p)continue;
  const effect=p.match(/^\[(kiss|giggle-old|giggle|oh|sigh)\]$/i);
  if(effect){
   const key=effect[1].toLowerCase()==='giggle-old'?'giggle_old':effect[1].toLowerCase();
   segments.push({type:'effect',url:effects[key]});continue;
  }
  const pause=p.match(/^\[pause:\s*(\d{1,4})ms\]$/i);
  if(pause){segments.push({type:'pause',ms:Math.min(3000,Number(pause[1])),status:'ready'});continue;}
  for(const chunk of smartSpeechChunks(p)){
   const previous=segments[segments.length-1];
   if(previous?.type==='speech')segments.push({type:'pause',ms:boundaryPause(previous.text),status:'ready'});
   segments.push({type:'speech',text:chunk,status:'queued'});
  }
 }
 return segments;
}

let modelPromise=null;
async function getModel(){if(!modelPromise)modelPromise=(async()=>{const {PiperNativeTTS}=await import('pipertts');return PiperNativeTTS.load({model:'hub:warmf-english-en-medium',modelsDir:'./models'});})().catch(e=>{modelPromise=null;throw e;});return modelPromise;}
async function compressWav(wav){return new Promise(done=>{const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-i','pipe:0','-ac','1','-c:a','libopus','-b:a','24k','-f','ogg','pipe:1']);const parts=[];let failed=false;ff.on('error',()=>{failed=true;done({audio:wav,mime:'audio/wav'});});ff.stdout.on('data',x=>parts.push(x));ff.on('close',code=>{if(!failed)done(code===0&&parts.length?{audio:Buffer.concat(parts),mime:'audio/ogg'}:{audio:wav,mime:'audio/wav'});});ff.stdin.on('error',()=>{});ff.stdin.end(wav);});}
let queue=Promise.resolve();
async function renderTask(task){
 try{
  task.status='loading';
  const tts=await getModel();
  task.status='generating';
  for(let i=0;i<task.segments.length;i++){
   const segment=task.segments[i];
   if(segment.type==='speech'){
    segment.status='generating';
    const {audio}=await tts.synthesize(segment.text,{speakerId:0});
    const compressed=await compressWav(Buffer.from(audio));
    segment.audio=compressed.audio;segment.mime=compressed.mime;segment.status='ready';
   }
  }
  task.status='ready';
 }catch(e){task.status='error';task.error=String(e?.message||e);}
}
function startTask(script){
 const id=crypto.randomUUID();
 const task={id,status:'queued',segments:parseScript(script),error:''};
 tasks.set(id,task);latestTask=id;
 while(tasks.size>8)tasks.delete(tasks.keys().next().value);
 queue=queue.catch(()=>{}).then(()=>renderTask(task));
 return task;
}

function makeServer() {
  const server = new McpServer({ name: 'piper-audio-test', version: '1.0.0' });
  registerAppResource(server, 'piper-warmf-legacy-player', URI, {}, async () => {
    const html = `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="background:white;color:#111;padding:16px;font:16px system-ui">
<h3>Piper WARMF + kiss test</h3><p>Speech first, then kiss. Credit: Lemonjolly (CC BY 4.0).</p>
<p id="status">Checking recording...</p>
<audio id="player" controls preload="metadata" style="display:none;width:100%;min-height:54px"></audio>
<script>
let ready=false;
const player=document.getElementById('player');
const voiceUrl='https://np-douce-audio-test-mcp.onrender.com/audio-test/audio?v=p225-20261104';
const kissUrl='https://cdn.freesound.org/previews/275/275345_3173139-hq.mp3';
let stage='voice';
player.addEventListener('ended',async()=>{if(stage==='voice'){stage='kiss';player.src=kissUrl;document.getElementById('status').textContent='Playing kiss sound';try{await player.play();}catch(e){document.getElementById('status').textContent='Tap Play for kiss';}}else{document.getElementById('status').textContent='Finished';stage='voice';player.src=voiceUrl;}});
async function poll(){
  try{
    const response=await fetch('https://np-douce-audio-test-mcp.onrender.com/audio-test/status?v=p225-20261104',{cache:'no-store'});
    if(!response.ok)throw Error('Server unavailable');
    const data=await response.json();
    document.getElementById('status').textContent=data.status==='ready'?'Ready to play':data.status==='error'?'Error: '+data.error:'Status: '+data.status;
    if(data.status==='ready'&&!ready){
      ready=true;
      player.src=voiceUrl;
      player.style.display='block';
    }
    if(data.status==='error')return;
  }catch(err){document.getElementById('status').textContent='Waiting for server: '+err.message;}
  if(!ready)setTimeout(poll,1500);
}
poll();
</script></body></html>`;
    return { contents: [{ uri: URI, mimeType: RESOURCE_MIME_TYPE, text: html }] };
  });
  registerAppTool(server, 'test_piper_p225_kiss_v6', {
    title: 'Piper WARMF + kiss ending test',
    description: "Play Piper WARMF speech followed by Lemonjolly's licensed kiss recording in one player.",
    inputSchema: {},
    annotations: { readOnlyHint: true },
    _meta: { ui: { resourceUri: URI }, 'openai/outputTemplate': URI }
  }, async () => {
    startGeneration();
    return { content: [{ type: 'text', text: status === 'ready' ? 'Piper greeting is ready. Tap Play when ready.' : 'Piper status: ' + status + (status === 'error' ? '. ' + errorMessage : '. Run again after generation completes.') }] };
  });

  registerAppResource(server,'piper-dynamic-player',URI7,{},async()=>{
   const html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body>
<style>
:root{color-scheme:dark;font:13px system-ui,sans-serif}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:transparent}
.voice-card{width:100%;max-width:380px;padding:12px 14px;border:1px solid #39333f;border-radius:16px;background:#19171e;color:#eee8f4}
.voice-header{display:flex;align-items:center;justify-content:space-between;gap:12px}
.voice-title{font-size:13px;font-weight:600;letter-spacing:.03em}
.voice-dot{display:inline-block;width:6px;height:6px;margin-right:7px;border-radius:50%;background:#b59aca}
#status{margin:6px 0 8px;font-size:11px;color:#bdb3c8;overflow-wrap:anywhere}
#player{width:100%;height:34px;display:none}
#replay{display:none;padding:5px 9px;border:1px solid #51425d;border-radius:20px;background:#2b2334;color:#e6d8f1;font:inherit;font-size:11px;cursor:pointer}
#replay:hover{background:#3a2c46}
#replay:focus-visible{outline:2px solid #c8a9e1;outline-offset:3px}
.credits{margin:8px 0 0;font-size:10px;color:#aa9fb5}
.credits summary{cursor:pointer;width:fit-content}
.credits p{margin:5px 0 0}
</style>
<section class="voice-card" aria-label="Desiree voice player">
<div class="voice-header"><span class="voice-title"><span class="voice-dot" aria-hidden="true"></span>Desi · Voice</span><button id="replay" type="button" aria-label="Replay from beginning">↻ Replay</button></div>
<p id="status" role="status" aria-live="polite">Loading voice…</p>
<audio id="player" controls aria-label="Voice playback"></audio>
<details class="credits"><summary>Sound credits</summary><p>Effects: Lemonjolly (CC BY 4.0); DarkNightPrincess (CC0), Freesound.</p></details>
</section>
<script>
const base='${BASE}',audio=document.getElementById('player'),statusEl=document.getElementById('status');
let task=null,index=0,pauseTimer=null,lockedId=null;
function acceptTask(payload){
 const o=payload?.structuredContent??payload?.result?.structuredContent??payload?.toolOutput?.structuredContent??payload?.toolOutput??payload;
 const id=o?.taskId??o?.task_id;
 if(typeof id==='string'&&/^[a-f0-9-]{36}$/i.test(id)&&id!==lockedId){
  lockedId=id;task=null;index=0;
  if(pauseTimer!==null){clearTimeout(pauseTimer);pauseTimer=null;}
  audio.pause();audio.removeAttribute('src');audio.load();
  audio.style.display='none';replay.style.display='none';
  statusEl.textContent='Preparing this reply audio';
  poll();
 }
}
acceptTask(window.openai?.toolOutput);
window.addEventListener('message',e=>{
 if(e.source!==window.parent||e.data?.jsonrpc!=='2.0')return;
 if(e.data.method==='ui/notifications/tool-result'||e.data.method==='ui/notifications/tool-input')acceptTask(e.data.params);
});
const replay=document.getElementById('replay');
function setFirstSegment(){
 if(!task)return;
 index=0;
 const first=task.segments[0];
 if(first?.type==='pause'){audio.removeAttribute('src');audio.load();return;}
 audio.src=first.type==='effect'?first.url:base+'/audio-test/v7/audio/'+task.id+'/0';
 index=1;
}
replay.addEventListener('click',async()=>{
 if(!task)return;
 if(pauseTimer!==null){clearTimeout(pauseTimer);pauseTimer=null;}
 audio.pause();setFirstSegment();statusEl.textContent='Replaying from beginning';
 if(task.segments[0]?.type==='pause'){await next();return;}
 try{await audio.play();}catch(e){statusEl.textContent='Tap Play to replay';}
});
async function next(){
 if(!task)return;
 if(index>=task.segments.length){statusEl.textContent='Finished';return;}
 if(task.segments[index].type==='speech'&&task.segments[index].status!=='ready'){statusEl.textContent='Waiting for next speech chunk';try{const r=await fetch(base+'/audio-test/v7/status?id='+lockedId,{cache:'no-store'});const d=await r.json();if(d.status==='missing'){statusEl.textContent='Render restarted; request a new recording';return;}if(d.status==='error'){statusEl.textContent='Error: '+d.error;return;}task=d;}catch(e){statusEl.textContent='Waiting for Render';}setTimeout(next,1500);return;}
 const segment=task.segments[index++];
 if(segment.type==='pause'){statusEl.textContent='Pause';pauseTimer=setTimeout(()=>{pauseTimer=null;next();},segment.ms);return;}
 audio.src=segment.type==='effect'?segment.url:base+'/audio-test/v7/audio/'+task.id+'/'+(index-1);
 audio.style.display='block';statusEl.textContent=segment.type==='speech'?'Speaking':'Playing expression';
 try{await audio.play();}catch(e){statusEl.textContent='Tap Play to continue';}
}
audio.addEventListener('ended',next);
async function poll(){
 try{
  const r=await fetch(base+'/audio-test/v7/status?id='+encodeURIComponent(lockedId),{cache:'no-store'});
  const d=await r.json();
  if(!lockedId){statusEl.textContent='Waiting for recording ID';setTimeout(poll,1000);return;}
  if(d.status==='missing'){statusEl.textContent='Render restarted; request a new recording';return;}
  if(d.segments?.[0]?.status==='ready'||(d.segments?.[0]?.type!=='speech'&&d.segments?.length)){task=d;statusEl.textContent='Ready to play';setFirstSegment();audio.style.display='block';replay.style.display='inline-block';statusEl.textContent='Attempting automatic playback';try{await audio.play();statusEl.textContent='Playing';}catch(e){statusEl.textContent='Autoplay blocked by browser. Tap Play to begin.';}return;}
  statusEl.textContent=d.status==='error'?'Error: '+d.error:'Status: '+d.status;
 }catch(e){statusEl.textContent='Waiting for server';}
 setTimeout(poll,1600);
}
poll();
</script></body></html>`;
   return {contents:[{uri:URI7,mimeType:RESOURCE_MIME_TYPE,text:html}]};
  });
  registerAppTool(server,'compose_piper_audio_v7',{
   title:'Piper WARMF dynamic speech and expressions',
   description:'Speak text with one audio player and optional [kiss], [giggle], [giggle-old], [oh], [sigh], or [pause:500ms] markers.',
   inputSchema:{script:z.string().min(1).max(1200)},
   _meta:{ui:{resourceUri:URI7},'openai/outputTemplate':URI7}
  },async({script})=>{
   const task=startTask(script);
   return {content:[{type:'text',text:'Queued audio script '+task.id+'. The embedded player will load it.'}],structuredContent:{taskId:task.id,status:'queued'}};
  });
  return server;
}
const port = Number(process.env.PORT || 8787);
createServer(async (req, res) => {
  const url = new URL(req.url || '/', 'http://localhost');

  if(url.pathname==='/audio-test/v7/status'&&req.method==='GET'){
   const task=tasks.get(url.searchParams.get('id')||latestTask);
   res.writeHead(200,{'content-type':'application/json','cache-control':'no-store','access-control-allow-origin':'*'});
   res.end(JSON.stringify(task?{id:task.id,status:task.status,error:task.error,segments:task.segments.map(({type,text,url,ms,status,mime})=>({type,text,url,ms,status,mime}))}:{status:url.searchParams.get('id')?'missing':'idle'}));return;
  }
  if(url.pathname.startsWith('/audio-test/v7/audio/')&&req.method==='GET'){
   const [, , , ,id,number]=url.pathname.split('/');
   const task=tasks.get(id),segment=task?.segments[Number(number)];
   if(!segment?.audio){res.writeHead(404).end('Not ready');return;}
   res.writeHead(200,{'content-type':segment.mime||'audio/wav','content-length':segment.audio.length,'access-control-allow-origin':'*','cache-control':'no-store'});
   res.end(segment.audio);return;
  }
  if (url.pathname === '/audio-test/status' && req.method === 'GET') {
    res.writeHead(200, {'content-type':'application/json','cache-control':'no-store','access-control-allow-origin':'*'});
    res.end(JSON.stringify({status,error:errorMessage}));return;
  }
  if (url.pathname === '/audio-test/audio' && req.method === 'GET') {
    if (!audioData) {res.writeHead(404).end('Audio not ready');return;}
    const audio=Buffer.from(audioData.split(',')[1],'base64');
    res.writeHead(200,{'content-type':'audio/wav','content-length':audio.length,'cache-control':'no-store','access-control-allow-origin':'*'});
    res.end(audio);return;
  }
  if (url.pathname === '/' && req.method === 'GET') { res.writeHead(200, { 'content-type': 'text/plain' }); res.end('Piper greeting MCP: ' + status); return; }
  if (url.pathname !== '/mcp') { res.writeHead(404).end('Not found'); return; }
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Expose-Headers', 'Mcp-Session-Id');
  if (req.method === 'OPTIONS') { res.writeHead(204, { 'Access-Control-Allow-Methods': 'POST, GET, DELETE, OPTIONS', 'Access-Control-Allow-Headers': 'content-type, mcp-session-id, mcp-protocol-version, accept' }).end(); return; }
  const server = makeServer();
  const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined, enableJsonResponse: true });
  try { await server.connect(transport); await transport.handleRequest(req, res); }
  catch (error) { console.error(error); if (!res.headersSent) res.writeHead(500).end('MCP error'); }
}).listen(port, '0.0.0.0', () => console.log('Piper greeting listening on ' + port));
